    """
    Given two sets, return the intersection of the two sets using a while loop.

    Args:
    set1 -- The first set
    set2 -- The second set

    Returns:
    A new set containing the common elements between set1 and set2

    Example:
    set1 = {1, 2, 3, 4, 5}
    set2 = {4, 5, 6, 7, 8}
    intersection_of_sets(set1, set2) => {4, 5}
    """

### Solution:

    result_set = set()

    # Loop through each element in set1
    set1_iterator = iter(set1)
    while True:
        try:
            set1_elem = next(set1_iterator)
        except StopIteration:
            break

        # Loop through each element in set2
        set2_iterator = iter(set2)
        while True:
            try:
                set2_elem = next(set2_iterator)
            except StopIteration:
                break

            # Check if the elements match
            if set1_elem == set2_elem:
                result_set.add(set1_elem)

    return

### Problem:
def find_lowest_temperature(temperatures):
    """
    Given a nested tuple of temperatures, find the lowest temperature among all nested tuples.

    Args:
        temperatures (tuple): A nested tuple representing temperatures.

    Returns:
        int: The lowest temperature value from the nested tuple.
    """

### Solution:


    lowest_temp = float('inf')
    nested_iter = iter(temperatures)

    while True:
        try:
            curr_tuple = next(nested_iter)
        except StopIteration:
            break

        if isinstance(curr_tuple, tuple):
            curr_temp = find_lowest_temperature(curr_tuple)

            if curr_temp < lowest_temp:
                lowest_temp = curr_temp
        else:
            if curr_tuple < lowest_temp:
                lowest_temp = curr_tuple

    return lowest_temp

